    correction: [{"quoi":"القاعدة","math":"الرباعي ABCD متوازي أضلاع إذا و فقط إذا كان الشعاعان AB و DC متساويين"},{"quoi":"نكتب تساوي الفاصلتين","math":"<span dir=\"ltr\" class=\"expr\">xB - xA = xC - xD</span>"},{"quoi":"نستخرج","math":"<span dir=\"ltr\" class=\"expr\">xD = 3 - 1 + (-3)</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">xD = -1</span>"},{"quoi":"نفعل نفس الشيء للترتيبة","math":"<span dir=\"ltr\" class=\"expr\">yD = (-10) - (-6) + (-1)</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">yD = -5</span>"},{"quoi":"نتحقّق بالقطرين","math":"إذن للقطرين [AC] و [BD] نفس المنتصف"},{"quoi":"النتيجة","math":"النقطة D إحداثياتها <span dir=\"ltr\" class=\"expr\">(-1</span> ; <span dir=\"ltr\" class=\"expr\">-5)</span>"}],
